// Search is the resolver for the search field.
func (r *queryResolver) Search(ctx context.Context, query string) ([]*model.Title, error) {
	query = strings.TrimSpace(query)
	if query == "" {
		return []*model.Title{}, nil
	}
	if utf8.RuneCountInString(query) > MaxQueryLength {
		return nil, userError("Search queries must be 100 characters or fewer", "BAD_USER_INPUT")
	}
	titles, err := r.TMDB.Search(ctx, query)
	if err != nil {
		slog.ErrorContext(ctx, "search failed", "err", err)
		if errors.Is(err, tmdb.ErrNotConfigured) {
			return nil, userError("Search is not configured", "NOT_CONFIGURED")
		}
		return nil, userError("Search is unavailable right now", "UNAVAILABLE")
	}
	out := make([]*model.Title, len(titles))
	for i, t := range titles {
		out[i] = toModel(t)
	}
	return out, nil
}

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

type queryResolver struct{ *Resolver }
